1	package com.maritime.platform.gateway.filter;
2	
3	import java.util.Set;
4	
5	import org.springframework.cloud.gateway.filter.GatewayFilterChain;
6	import org.springframework.cloud.gateway.filter.GlobalFilter;
7	import org.springframework.core.Ordered;
8	import org.springframework.core.annotation.Order;
9	import org.springframework.http.server.reactive.ServerHttpRequest;
10	import org.springframework.stereotype.Component;
11	import org.springframework.web.server.ServerWebExchange;
12	
13	import reactor.core.publisher.Mono;
14	
15	/**
16	 * Strips headers that must only be set by the gateway, never trusted from clients.
17	 * <p>
18	 * Runs for all requests &mdash; including public paths &mdash; before any
19	 * auth or logging filter sees the request, so no downstream component can be
20	 * tricked by client-supplied internal headers.
21	 */
22	@Component
23	@Order(GatewayFilterOrder.UNTRUSTED_HEADER_STRIP)
24	public class UntrustedHeaderStripFilter implements GlobalFilter, Ordered {
25	
26		// Headers that must only be set by the gateway, never trusted from clients.
27		// X-App-Key is intentionally excluded because HMAC auth reads it before the
28		// trusted-context injection phase.
29		static final Set<String> UNTRUSTED_HEADERS = Set.of(
30				"X-Internal-Call",
31				"X-User-Id", "X-User-Name",
32				"X-Active-Org-Code", "X-Active-Org-Name",
33				"X-Session-Id",
34				"X-System-Scope",
35				"X-User-Source",
36				"X-Tenant-Id", "X-Tenant-Code",
37				"X-App-Code", "X-App-Id",
38				"X-Verified-App-Code",
39				"X-App-Permissions",
40				"X-Trace-Id"
41		);
42	
43		@Override
44		public Mono<Void> filter(ServerWebExchange exchange, GatewayFilterChain chain) {
45			ServerHttpRequest mutated = exchange.getRequest().mutate()
46					.headers(headers -> UNTRUSTED_HEADERS.forEach(headers::remove))
47					.build();
48			return chain.filter(exchange.mutate().request(mutated).build());
49		}
50	
51		@Override
52		public int getOrder() {
53			return GatewayFilterOrder.UNTRUSTED_HEADER_STRIP;
54		}
55	}
