94		private MockServerWebExchange exchangeWithBody(String method, String path, String body) {
95			MockServerHttpRequest request = MockServerHttpRequest
96					.method(HttpMethod.valueOf(method), path)
97					.header(APP_KEY_HEADER, APP_KEY)
98					.header(TIMESTAMP_HEADER, "1700000000000")
99					.header(NONCE_HEADER, "nonce-0123456789abcdef")
100					.header(BODY_DIGEST_HEADER, "sha256-digest-placeholder")
101					.header(SIGNATURE_HEADER, "signature-placeholder")
102					.body(body != null ? body : "");
103			MockServerWebExchange exchange = MockServerWebExchange.from(request);
104			exchange.getAttributes().put(RouteSecurityPolicyFilter.POLICY_ATTR,
105					new RouteSecurityPolicy(AuthMode.HMAC, "hmac-route"));
106			return exchange;
107		}
