1	package com.maritime.platform.gateway.security;
2	
3	import java.util.ArrayList;
4	import java.util.Collections;
5	import java.util.HashSet;
6	import java.util.List;
7	import java.util.Locale;
8	import java.util.Set;
9	
10	import org.springframework.beans.factory.InitializingBean;
11	import org.springframework.beans.factory.annotation.Autowired;
12	import org.springframework.http.server.reactive.ServerHttpRequest;
13	import org.springframework.stereotype.Component;
14	import org.springframework.web.util.pattern.PathPattern;
15	import org.springframework.web.util.pattern.PathPatternParser;
16	import org.springframework.web.util.pattern.PatternParseException;
17	
18	@Component
19	public class RouteSecurityPolicyResolver implements InitializingBean {
20	
21		private final GatewaySecurityProperties properties;
22	
23		private final List<GatewaySecurityPolicyCustomizer> customizers;
24	
25		private final List<String> programmaticPublicPaths = new ArrayList<>();
26	
27		private final List<ProgrammaticRouteRule> programmaticRoutes = new ArrayList<>();
28	
29		private List<CompiledPublicPath> compiledPublicPaths = Collections.emptyList();
30	
31		private List<CompiledRouteRule> compiledRoutes = Collections.emptyList();
32	
33		private AuthMode defaultAuthMode;
34	
35		private volatile boolean initialized;
36	
37		public RouteSecurityPolicyResolver(GatewaySecurityProperties properties) {
38			this(properties, Collections.emptyList());
39		}
40	
41		@Autowired
42		public RouteSecurityPolicyResolver(GatewaySecurityProperties properties,
43		                                   List<GatewaySecurityPolicyCustomizer> customizers) {
44			this.properties = properties;
45			this.customizers = customizers != null ? customizers : Collections.emptyList();
46		}
47	
48		// ---------- programmatic registration (for customizers) ----------
49	
50		public void addPublicPath(String publicPath) {
51			checkNotInitialized();
52			programmaticPublicPaths.add(publicPath);
53		}
54	
55		public void addRoutePolicy(String id, List<String> paths, List<String> methods, AuthMode authMode) {
56			checkNotInitialized();
57			if (authMode == null) {
58				throw new IllegalArgumentException(
59						"Route '" + id + "' authMode must not be null");
60			}
61			if (authMode == AuthMode.JWT_AND_HMAC) {
62				throw new IllegalArgumentException(
63						"Route '" + id + "' uses JWT_AND_HMAC which is reserved and not yet implemented");
64			}
65			programmaticRoutes.add(new ProgrammaticRouteRule(id, paths, methods, authMode));
66		}
67	
68		// ---------- resolution ----------
69	
70		public RouteSecurityPolicy resolve(ServerHttpRequest request) {
71			return resolve(request.getURI().getPath(), request.getMethod() != null ? request.getMethod().name() : null);
72		}
73	
74		public RouteSecurityPolicy resolve(String path, String httpMethod) {
75			if (!initialized) {
76				compile();
77			}
78			// 1. Public paths take absolute priority — always NONE
79			for (CompiledPublicPath cpp : compiledPublicPaths) {
80				if (cpp.pattern.matches(PathContainerAdapter.parse(path))) {
81					return new RouteSecurityPolicy(AuthMode.NONE, cpp.ruleId);
82				}
83			}
84			// 2. Route policies
85			for (CompiledRouteRule crr : compiledRoutes) {
86				if (crr.matches(path, httpMethod)) {
87					return new RouteSecurityPolicy(crr.authMode, crr.ruleId);
88				}
89			}
90			// 3. Default
91			return new RouteSecurityPolicy(defaultAuthMode, "DEFAULT");
92		}
93	
94		public AuthMode getDefaultAuthMode() {
95			return defaultAuthMode;
96		}
97	
98		// ---------- initialization ----------
99	
100		@Override
101		public void afterPropertiesSet() {
102			compile();
103		}
104	
105		private void compile() {
106			if (initialized) {
107				return;
108			}
109			PathPatternParser parser = new PathPatternParser();
110			parser.setMatchOptionalTrailingSeparator(true);
111	
112			List<CompiledPublicPath> publicPatterns = new ArrayList<>();
113			List<CompiledRouteRule> routeRules = new ArrayList<>();
114	
115			// Apply customizers to collect programmatic registrations
116			for (GatewaySecurityPolicyCustomizer customizer : customizers) {
117				customizer.customize(this);
118			}
119	
120			// Compile public paths from properties
121			for (String path : properties.getPublicPaths()) {
122				publicPatterns.add(new CompiledPublicPath(compilePattern(parser, path), "PUBLIC:" + path));
123			}
124			// Compile programmatic public paths
125			for (String path : programmaticPublicPaths) {
126				publicPatterns.add(new CompiledPublicPath(compilePattern(parser, path), "PUBLIC(custom):" + path));
127			}
128	
129			// Compile route policies from properties
130			for (GatewaySecurityProperties.RoutePolicy rp : properties.getRoutes()) {
131				Set<String> methods = uppercaseSet(rp.getMethods());
132				for (String path : rp.getPaths()) {
133					routeRules.add(new CompiledRouteRule(
134							compilePattern(parser, path), rp.getId(), methods, rp.getAuthMode()));
135				}
136			}
137			// Compile programmatic route policies
138			for (ProgrammaticRouteRule pr : programmaticRoutes) {
139				Set<String> methods = uppercaseSet(pr.methods);
140				for (String path : pr.paths) {
141					routeRules.add(new CompiledRouteRule(
142							compilePattern(parser, path), pr.id, methods, pr.authMode));
143				}
144			}
145	
146			this.compiledPublicPaths = Collections.unmodifiableList(publicPatterns);
147			this.compiledRoutes = Collections.unmodifiableList(routeRules);
148			this.defaultAuthMode = properties.getDefaultAuthMode();
149			this.initialized = true;
150		}
151	
152		private static PathPattern compilePattern(PathPatternParser parser, String pattern) {
153			try {
154				return parser.parse(pattern);
155			} catch (PatternParseException e) {
156				throw new IllegalStateException("Invalid path pattern '" + pattern + "': " + e.getMessage(), e);
157			}
158		}
159	
160		private static Set<String> uppercaseSet(List<String> values) {
161			if (values == null || values.isEmpty()) {
162				return Collections.emptySet();
163			}
164			Set<String> set = new HashSet<>(values.size());
165			for (String v : values) {
166				if (v != null && !v.isBlank()) {
167					set.add(v.strip().toUpperCase(Locale.ROOT));
168				}
169			}
170			return Collections.unmodifiableSet(set);
171		}
172	
173		private void checkNotInitialized() {
174			if (initialized) {
175				throw new IllegalStateException(
176						"RouteSecurityPolicyResolver is already initialized. " +
177						"addPublicPath / addRoutePolicy must be called from a GatewaySecurityPolicyCustomizer.");
178			}
179		}
180	
181		// ---------- internal types ----------
182	
183		private static class CompiledPublicPath {
184			final PathPattern pattern;
185			final String ruleId;
186	
187			CompiledPublicPath(PathPattern pattern, String ruleId) {
188				this.pattern = pattern;
189				this.ruleId = ruleId;
190			}
191		}
192	
193		private static class CompiledRouteRule {
194			final PathPattern pattern;
195			final String ruleId;
196			final Set<String> methods;
197			final AuthMode authMode;
198	
199			CompiledRouteRule(PathPattern pattern, String ruleId, Set<String> methods, AuthMode authMode) {
200				this.pattern = pattern;
201				this.ruleId = ruleId;
202				this.methods = methods;
203				this.authMode = authMode;
204			}
205	
206			boolean matches(String path, String httpMethod) {
207				if (!this.pattern.matches(PathContainerAdapter.parse(path))) {
208					return false;
209				}
210				if (methods.isEmpty()) {
211					return true;
212				}
213				if (httpMethod == null) {
214					return false;
215				}
216				return methods.contains(httpMethod.toUpperCase(Locale.ROOT));
217			}
218		}
219	
220		private static class ProgrammaticRouteRule {
221			final String id;
222			final List<String> paths;
223			final List<String> methods;
224			final AuthMode authMode;
225	
226			ProgrammaticRouteRule(String id, List<String> paths, List<String> methods, AuthMode authMode) {
227				this.id = id;
228				this.paths = paths != null ? paths : Collections.emptyList();
229				this.methods = methods != null ? methods : Collections.emptyList();
230				this.authMode = authMode;
231			}
232		}
233	
234		/**
235		/**
236		 * Adapter that bridges a string path to {@link org.springframework.http.server.PathContainer}
237		 * without requiring the spring-web dependency at the API level.
238		 */
239		private static final class PathContainerAdapter {
240			private PathContainerAdapter() {}
241	
242			static org.springframework.http.server.PathContainer parse(String path) {
243				return org.springframework.http.server.PathContainer.parsePath(path);
244			}
245		}
246	}
