115				GatewaySecurityProperties.Headers hdrs, ServerWebExchange exchange) {
116			ServerHttpRequest headerStripped = request.mutate()
117					.headers(h -> {
118						h.remove(hdrs.getAppKey());
119						h.remove(hdrs.getTimestamp());
120						h.remove(hdrs.getNonce());
121						h.remove(hdrs.getBodyDigest());
122						h.remove(hdrs.getSignature());
123					})
124					.build();
125			return new ServerHttpRequestDecorator(headerStripped) {
126				@Override
127				public Flux<DataBuffer> getBody() {
128					return headerStripped.getBody();
129				}
130			};
131		}
132	
133		/**
134		 * Reads the request body once, caches the bytes, and returns a decorated exchange
135		 * whose request body can be re-read by downstream filters and handlers.
136		 */
137		private Mono<ServerWebExchange> readAndCacheBody(ServerWebExchange exchange) {
138			return DataBufferUtils.join(exchange.getRequest().getBody())
139					.map(buf -> {
140						byte[] bytes = new byte[buf.readableByteCount()];
141						buf.read(bytes);
142						DataBufferUtils.release(buf);
143						return bytes;
144					})
145					.switchIfEmpty(Mono.just(new byte[0]))
146					.map(bytes -> {
147						ServerHttpRequest decorated = new ServerHttpRequestDecorator(exchange.getRequest()) {
148							@Override
149							public Flux<DataBuffer> getBody() {
150								return Flux.just(
151										exchange.getResponse().bufferFactory().wrap(bytes));
152							}
153						};
154						ServerWebExchange cached = exchange.mutate().request(decorated).build();
155						cached.getAttributes().put("gateway.cachedBody", bytes);
156						return cached;
157					});
158		}
159	
160		private boolean hasBearerToken(ServerWebExchange exchange) {
161			String auth = exchange.getRequest().getHeaders().getFirst("Authorization");
162			return auth != null && auth.startsWith("Bearer ");
163		}
164	
165		private boolean isAnyBlank(String... values) {
166			for (String v : values) {
167				if (v == null || v.isBlank()) {
168					return true;
169				}
170			}
171			return false;
172		}
173	
174	}
