615								.header("X-User-Id", "forged-user")
616								.header("X-App-Code", "forged-app")
617								.header("X-Tenant-Id", "fake-tenant"));
618	
619				// Strip
620				AtomicReference<ServerWebExchange> afterStrip = new AtomicReference<>();
621				strip.filter(exchange, capturingChain(afterStrip)).block();
622				ServerWebExchange stripped = afterStrip.get();
623	
624				// No principal on public path
625				assertThat((Object) stripped.getAttribute(GatewayPrincipal.ATTRIBUTE)).isNull();
626	
627				// Inject (should pass through since no principal)
628				AtomicReference<ServerWebExchange> afterInjection = new AtomicReference<>();
629				inject.filter(stripped, capturingChain(afterInjection)).block();
630				ServerWebExchange finalExchange = afterInjection.get();
631	
632				var finalHeaders = finalExchange.getRequest().getHeaders();
633				assertThat(finalHeaders.getFirst("X-User-Id")).isNull();
634				assertThat(finalHeaders.getFirst("X-App-Code")).isNull();
635				assertThat(finalHeaders.getFirst("X-Tenant-Id")).isNull();
636			}
637		}
638	
639		// ---------- helpers ----------
640	
641		private static GatewayFilterChain capturingChain(AtomicReference<ServerWebExchange> ref) {
642			return exchange -> {
643				if (ref != null) {
644					ref.set(exchange);
645				}
646				return Mono.empty();
647			};
648		}
649	}
