			assertThat(ann.value()).isEqualTo(GatewayFilterOrder.UNTRUSTED_HEADER_STRIP);
		}

		@Test
		@DisplayName("RequestLog order is HIGHEST_PRECEDENCE + 10")
		void requestLogOrder() {
