			assertThat(policy).isNotNull();
			assertThat(policy.getAuthMode()).isEqualTo(AuthMode.NONE);

			// Response has trace ID
			assertThat(e5.getResponse().getHeaders().getFirst(TraceIdGatewayFilter.TRACE_ID_HEADER))
					.isNotNull();
		}

